    Bug 1935109 - Add a pref to optionally disable self-healing of corrupted offline messages. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D231079

diff --git a/mailnews/base/src/nsMsgDBFolder.cpp b/mailnews/base/src/nsMsgDBFolder.cpp
index b6cd4f24710..aa86d58a9a3 100644
--- a/mailnews/base/src/nsMsgDBFolder.cpp
+++ b/mailnews/base/src/nsMsgDBFolder.cpp
@@ -82,6 +82,7 @@ static PRTime gtimeOfLastPurgeCheck;  // variable to know when to check for
 #define PREF_MAIL_PURGE_THRESHOLD_MB "mail.purge_threshhold_mb"
 #define PREF_MAIL_PURGE_ASK "mail.purge.ask"
 #define PREF_MAIL_WARN_FILTER_CHANGED "mail.warn_filter_changed"
+#define PREF_MAIL_DISCARD_OFFLINE_ON_FAILURE "mail.discard_offline_msg_on_failure"

 const char* kUseServerRetentionProp = "useServerRetention";

@@ -1084,6 +1085,17 @@ NS_IMETHODIMP nsMsgDBFolder::HasMsgOffline(nsMsgKey msgKey, bool* result) {
 }

 NS_IMETHODIMP nsMsgDBFolder::DiscardOfflineMsg(nsMsgKey msgKey) {
+  nsCOMPtr<nsIPrefService> pref =
+      do_GetService(NS_PREFSERVICE_CONTRACTID);
+  nsCOMPtr<nsIPrefBranch> branch;
+  pref->GetBranch("", getter_AddRefs(branch));
+
+  bool allowDiscard = true;
+  branch->GetBoolPref(PREF_MAIL_DISCARD_OFFLINE_ON_FAILURE, &allowDiscard);
+  if (!allowDiscard) {
+    return NS_OK;
+  }
+
   GetDatabase();
   if (!mDatabase) return NS_ERROR_FAILURE;

diff --git a/mailnews/mailnews.js b/mailnews/mailnews.js
index 5b589f705fe..7419bf7c6fa 100644
--- a/mailnews/mailnews.js
+++ b/mailnews/mailnews.js
@@ -363,6 +363,10 @@ pref("mail.purge_threshhold_mb", 500);
 pref("mail.prompt_purge_threshhold", true);
 pref("mail.purge.ask", true);

+// If true, a failure to read a message from offline storage will
+// discard it, to allow subsequent automatic reloading (self-healing).
+pref("mail.discard_offline_msg_on_failure", true);
+
 pref("mailnews.offline_sync_mail", false);
 pref("mailnews.offline_sync_news", false);
 pref("mailnews.offline_sync_send_unsent", true);
